@inherits UmbracoViewPage<BlogPost>
@{
    Layout = "~/Views/Shared/_Layout.cshtml";
    ViewData["Title"] = Model.Name;
    var home = Model.AncestorOrSelf<BlogFrontPage>();
}
<article>
    <header class="max-w-3xl mx-auto">
        <a href="@(home?.Url() ?? "/")" class="text-sm font-medium text-indigo-700">&larr; All posts</a>
        <p class="mt-6 text-xs font-semibold uppercase tracking-wide text-indigo-600">
            @Model.PublishDate.ToString("d MMMM yyyy")@(string.IsNullOrEmpty(Model.Author) ? "" : $" · {Model.Author}")
        </p>
        <h1 class="mt-3 text-4xl sm:text-5xl font-bold tracking-tight text-slate-900">@Model.Name</h1>
        @if (!string.IsNullOrEmpty(Model.Summary))
        {
            <p class="mt-6 text-xl text-slate-600 leading-relaxed">@Model.Summary</p>
        }
    </header>
    @if (Model.HeroImage is not null)
    {
        <img src="@Model.HeroImage.GetCropUrl(width: 1800, height: 800)" alt="@Model.HeroImage.Name" class="mt-10 w-full rounded-3xl object-cover aspect-[9/4]" />
    }
    <div class="mt-12">
        @await Html.GetBlockGridHtmlAsync(Model, "blocks")
    </div>
</article>
=== Views/Shared/_Layout.cshtml
@inherits UmbracoViewPage
@{
    var home = Model.AncestorOrSelf<BlogFrontPage>();
    var title = ViewData["Title"] as string ?? Model.Name;
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@title · The MCP Blog</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</head>
<body class="min-h-screen bg-slate-50 text-slate-900 antialiased">
    <header class="border-b border-slate-200 bg-white">
        <div class="mx-auto max-w-6xl px-6 py-5 flex items-center justify-between">
            <a href="@(home?.Url() ?? "/")" class="text-lg font-bold tracking-tight">The MCP Blog</a>
            <span class="text-sm text-slate-500">Built with Umbraco, over MCP</span>
        </div>
    </header>
    <main class="mx-auto max-w-6xl px-6 py-12">
        @RenderBody()
    </main>
    <footer class="border-t border-slate-200 mt-16">
        <div class="mx-auto max-w-6xl px-6 py-8 text-sm text-slate-500">
            Photos from Unsplash, credited in their captions. Content modelled and published through the Umbraco MCP server.
        </div>
    </footer>
</body>
</html>
